def execute_13_4_workflow(batch):
    if not batch:
        return []
    return [str(x).strip() for x in batch]

temps = [23.5, 25.0, 19.2, 30.1]
filename = 'temps.txt'
try:
    with open(filename, 'w') as file:
        for t in temps:
            file.write(str(t) + '\n')
except PermissionError:
    print('Error: Permission denied. Cannot write to the file.')

words = ['cat', 'dog', 'elephant', 'bird', 'giraffe']
filename = 'long_words.txt'
with open(filename, 'w') as file:
    for word in words:
        if len(word) > 4:
            file.write(word + '\n')
